const input = $json.body ?? $json;

const text = (value) =>
  value === null || value === undefined
    ? ''
    : String(value).trim();

const bool = (value) =>
  typeof value === 'boolean'
    ? value
    : ['true', '1', 'yes', 'on'].includes(
        text(value).toLowerCase()
      );

const hash = (value) => {
  let current = 2166136261;

  for (let index = 0; index < value.length; index++) {
    current ^= value.charCodeAt(index);
    current = Math.imul(current, 16777619);
  }

  return (current >>> 0)
    .toString(16)
    .padStart(8, '0');
};

const clinic_name = text(input.clinic_name);
const mobile = text(input.mobile);
const channel = text(input.channel).toLowerCase();
const purpose = text(input.purpose).toLowerCase();
const message_type =
  text(input.message_type || 'text').toLowerCase();
const template_code = text(input.template_code);
const language =
  text(input.language || 'fa').toLowerCase();
const subject = text(input.subject);
const message_text = text(input.message_text);
const related_entity_type =
  text(input.related_entity_type);
const related_entity_id =
  Number(input.related_entity_id ?? 0);
const request_reference =
  text(input.request_reference);
const priority = Number(input.priority ?? 5);
const scheduled_at =
  text(input.scheduled_at) ||
  new Date().toISOString();
const max_attempts =
  Number(input.max_attempts ?? 5);
const webhook_base_url =
  text(
    input.webhook_base_url ||
    'http://localhost:5678/webhook'
  ).replace(/\/+$/, '');
const confirm_queue = bool(input.confirm_queue);

let payload = input.payload ?? {};

try {
  if (typeof payload === 'string') {
    payload = JSON.parse(payload || '{}');
  }
} catch {
  payload = null;
}

const generatedKeySource = [
  clinic_name,
  mobile,
  channel,
  purpose,
  request_reference,
  related_entity_type,
  related_entity_id,
  scheduled_at,
  message_text,
].join('|');

const idempotency_key =
  text(input.idempotency_key) ||
  `msg-${hash(generatedKeySource)}`;

const channels = [
  'whatsapp',
  'sms',
  'email',
  'phone',
  'web_push',
  'in_app',
];

const purposes = [
  'appointment_reminder',
  'appointment_update',
  'waitlist_offer',
  'post_visit_followup',
  'clinical_followup',
  'marketing',
  'satisfaction_survey',
  'general_information',
  'human_handoff',
];

const messageTypes = [
  'text',
  'template',
  'media',
  'interactive',
  'email',
];

const errors = [];

if (!clinic_name) {
  errors.push({
    field: 'clinic_name',
    message: 'نام کلینیک الزامی است.',
  });
}

if (!/^\+?[0-9]{8,15}$/.test(mobile)) {
  errors.push({
    field: 'mobile',
    message: 'شماره گیرنده معتبر نیست.',
  });
}

if (!channels.includes(channel)) {
  errors.push({
    field: 'channel',
    message: 'کانال معتبر نیست.',
  });
}

if (!purposes.includes(purpose)) {
  errors.push({
    field: 'purpose',
    message: 'هدف پیام معتبر نیست.',
  });
}

if (!messageTypes.includes(message_type)) {
  errors.push({
    field: 'message_type',
    message: 'نوع پیام معتبر نیست.',
  });
}

if (!['fa', 'en', 'ar', 'unknown'].includes(language)) {
  errors.push({
    field: 'language',
    message: 'زبان معتبر نیست.',
  });
}

if (!message_text) {
  errors.push({
    field: 'message_text',
    message: 'متن پیام الزامی است.',
  });
}

if (message_text.length > 12000) {
  errors.push({
    field: 'message_text',
    message: 'متن پیام بیش از حد طولانی است.',
  });
}

if (
  !payload ||
  Array.isArray(payload) ||
  typeof payload !== 'object'
) {
  errors.push({
    field: 'payload',
    message: 'payload باید یک شیء JSON باشد.',
  });
  payload = {};
}

if (
  !Number.isInteger(related_entity_id) ||
  related_entity_id < 0
) {
  errors.push({
    field: 'related_entity_id',
    message: 'شناسه موجودیت مرتبط معتبر نیست.',
  });
}

if (
  !Number.isInteger(priority) ||
  priority < 1 ||
  priority > 9
) {
  errors.push({
    field: 'priority',
    message: 'اولویت باید بین 1 و 9 باشد.',
  });
}

if (Number.isNaN(Date.parse(scheduled_at))) {
  errors.push({
    field: 'scheduled_at',
    message: 'زمان برنامه‌ریزی معتبر نیست.',
  });
}

if (
  !Number.isInteger(max_attempts) ||
  max_attempts < 1 ||
  max_attempts > 20
) {
  errors.push({
    field: 'max_attempts',
    message: 'تعداد تلاش مجاز باید بین 1 و 20 باشد.',
  });
}

if (!/^https?:\/\/.+/i.test(webhook_base_url)) {
  errors.push({
    field: 'webhook_base_url',
    message: 'آدرس Webhook معتبر نیست.',
  });
}

if (confirm_queue !== true) {
  errors.push({
    field: 'confirm_queue',
    message: 'ثبت پیام در صف باید تأیید شود.',
  });
}

return [{
  json: {
    clinic_name,
    mobile,
    channel,
    purpose,
    message_type,
    template_code,
    language,
    subject,
    message_text,
    payload,
    payload_text: JSON.stringify(payload),
    related_entity_type,
    related_entity_id,
    request_reference,
    idempotency_key,
    priority,
    scheduled_at,
    max_attempts,
    webhook_base_url,
    permission_url:
      `${webhook_base_url}/clinic/communications/check-permission`,
    confirm_queue,
    validation_status:
      errors.length === 0 ? 'valid' : 'invalid',
    errors,
  },
}];
